class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, dilation: int = 1, bias: bool = False):
        super().__init__()
        self.conv1d = nn.Conv1d(in_channels, out_channels, kernel_size, stride=stride, dilation=dilation, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Perform 1D convolution using the custom CUDA operator `conv1d_cuda`.
        The weight and bias are taken from self.conv1d.
        """
        batch_size = x.size(0)
        in_channels = x.size(1)
        length = x.size(-1)

        n_out_len = max(0, (length - (kernel_size - 1) * dilation) // stride + 1)
        out_channels = self.conv1d.out_channels

        out = torch.zeros_like(x)

        const int block_size = 256
        const int num_blocks = (batch_size * out_channels * n_out_len + block_size - 1) // block_size

        # Launch the custom convolution kernel
        conv1d_kernel<<<num_blocks, block_size>>>(x.data_ptr(), self.conv1d.weight.data_ptr(), out.data_ptr(),
                                                   batch_size, in_channels, out_channels,
                                                   kernel_size, stride, dilation, length)

        return out
